#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Bilnov M3 - Viewer IFC v1 : panneau proprietes complet (property sets), coupes X/Y/Z, isoler/masquer, restauration de scene (Voir dans la maquette BIM -> focus objet via ?bimExpress). ADDITIF (ecrase Model3DViewer/locations). A appliquer apres 12. Necessite web-ifc (deja installe par 12)."""
import base64, os, sys, subprocess
FILES={"src/components/Model3DViewer.tsx": "", "src/lib/locations.ts": "", "src/lib/__tests__/locations.test.ts": ""}
def d(s): return base64.b64decode(s).decode('utf-8')
def parse(a):
    root,build='.',True; i=0
    while i<len(a):
        if a[i]=='--root': root=a[i+1]; i+=2; continue
        if a[i]=='--no-build': build=False
        i+=1
    return root,build
def run(cmd,root):
    print("\n$"," ".join(cmd)); r=subprocess.run(cmd,cwd=root)
    if r.returncode: print("!! echec (rc=%d)."%r.returncode); sys.exit(r.returncode)
def main():
    root,build=parse(sys.argv[1:]); print("== Bilnov M3 - viewer IFC v1 (proprietes/coupes/isolation/restauration) ==")
    for rel,enc in FILES.items():
        p=os.path.join(root,rel); os.makedirs(os.path.dirname(p),exist_ok=True); c=d(enc)
        if os.path.exists(p) and open(p,encoding='utf-8').read()==c: print("  = ",rel)
        else: open(p,'w',encoding='utf-8').write(c); print("  + ",rel)
    run(["npm","install"],root); run(["npm","run","test"],root)
    if build: run(["npm","run","build"],root)
    print("\nOK. Viewer IFC v1 applique. Aucun git push.")
if __name__=='__main__': main()
